  $input.first().json.mensaje || "Sin contenido";

return `
CORREO ENVIADO (SIMULADO)

Destinatario:
${destinatario}

Asunto:
${asunto}

Mensaje:
${mensaje}

Estado:
Correo procesado correctamente por DIMA AI Company.

Referencia:
CAMBRON-AI-MAIL-2026
`;
``

